  'agent/tools/schema/custom.action.schema.json':
    '{\n    "$schema": "https://json-schema.org/draft/2020-12/schema",\n    "$defs": {\n        "DisableNodeParam": {\n            "type": "object",\n            "properties": {\n                "node_name": {\n                    "type": "string",\n                    "minLength": 1,\n                    "description": "Pipeline node name to disable."\n                }\n            },\n            "required": [\n                "node_name"\n            ],\n            "additionalProperties": false\n        },\n        "NodeOverrideParam": {\n            "type": "object",\n            "description": "Object passed directly to context.override_pipeline(). Keys are pipeline node names.",\n            "minProperties": 1,\n            "additionalProperties": {\n                "type": "object",\n                "description": "Partial pipeline node override."\n            }\n        },\n        "ResetCountParam": {\n            "type": "object",\n            "properties": {\n                "nodes": {\n                    "type": "array",\n                    "items": {\n                        "type": "string",\n                        "minLength": 1\n                    },\n                    "minItems": 1,\n                    "description": "Pipeline node names whose hit counters should be cleared."\n                },\n                "strict": {\n                    "type": "boolean",\n                    "default": false,\n                    "description": "Whether the action should fail when any node cannot be cleared."\n                }\n            },\n            "required": [\n                "nodes"\n            ],\n            "additionalProperties": false\n        },\n        "SubTaskParam": {\n            "type": "object",\n            "properties": {\n                "sub": {\n                    "type": "array",\n                    "items": {\n                        "type": "string",\n                        "minLength": 1\n                    },\n                    "minItems": 1,\n                    "description": "Task names to run in order."\n                },\n                "continue": {\n                    "type": "boolean",\n                    "default": false,\n                    "description": "Whether to continue after a sub task fails."\n                },\n                "strict": {\n                    "type": "boolean",\n                    "default": true,\n                    "description": "Whether this action should fail when any sub task fails."\n                }\n            },\n            "required": [\n                "sub"\n            ],\n            "additionalProperties": false\n        }\n    },\n    "type": "object",\n    "properties": {\n        "custom_action": {\n            "type": "string",\n            "description": "Registered custom action name."\n        },\n        "custom_action_param": {\n            "description": "Parameters passed to the registered custom action."\n        }\n    },\n    "allOf": [\n        {\n            "if": {\n                "properties": {\n                    "custom_action": {\n                        "const": "DisableNode"\n                    }\n                },\n                "required": [\n                    "custom_action"\n                ]\n            },\n            "then": {\n                "properties": {\n                    "custom_action_param": {\n                        "$ref": "#/$defs/DisableNodeParam"\n                    }\n                },\n                "required": [\n                    "custom_action_param"\n                ]\n            }\n        },\n        {\n            "if": {\n                "properties": {\n                    "custom_action": {\n                        "const": "NodeOverride"\n                    }\n                },\n                "required": [\n                    "custom_action"\n                ]\n            },\n            "then": {\n                "properties": {\n                    "custom_action_param": {\n                        "$ref": "#/$defs/NodeOverrideParam"\n                    }\n                },\n                "required": [\n                    "custom_action_param"\n                ]\n            }\n        },\n        {\n            "if": {\n                "properties": {\n                    "custom_action": {\n                        "const": "ResetCount"\n                    }\n                },\n                "required": [\n                    "custom_action"\n                ]\n            },\n            "then": {\n                "properties": {\n                    "custom_action_param": {\n                        "$ref": "#/$defs/ResetCountParam"\n                    }\n                },\n                "required": [\n                    "custom_action_param"\n                ]\n            }\n        },\n        {\n            "if": {\n                "properties": {\n                    "custom_action": {\n                        "const": "SubTask"\n                    }\n                },\n                "required": [\n                    "custom_action"\n                ]\n            },\n            "then": {\n                "properties": {\n                    "custom_action_param": {\n                        "$ref": "#/$defs/SubTaskParam"\n                    }\n                },\n                "required": [\n                    "custom_action_param"\n                ]\n            }\n        }\n    ]\n}\n',
  'agent/tools/schema/custom.recognition.schema.json':
    '{\n    "$schema": "https://json-schema.org/draft/2020-12/schema",\n    "$defs": {\n        "Rect": {\n            "type": "array",\n            "items": {\n                "type": "integer"\n            },\n            "minItems": 4,\n            "maxItems": 4,\n            "description": "Recognition result box as [x, y, w, h]."\n        },\n        "ExampleRecognitionParam": {\n            "type": "object",\n            "properties": {\n                "node": {\n                    "type": "string",\n                    "minLength": 1,\n                    "description": "Existing recognition node to reuse through context.run_recognition()."\n                },\n                "template_node": {\n                    "type": "string",\n                    "minLength": 1,\n                    "description": "Alias of node, kept for examples that name reusable recognition nodes this way."\n                },\n                "box": {\n                    "$ref": "#/$defs/Rect"\n                },\n                "detail": {\n                    "type": "object",\n                    "description": "Extra detail object returned with CustomRecognition.AnalyzeResult."\n                }\n            },\n            "additionalProperties": true\n        }\n    },\n    "type": "object",\n    "properties": {\n        "custom_recognition": {\n            "type": "string",\n            "description": "Registered custom recognition name."\n        },\n        "custom_recognition_param": {\n            "description": "Parameters passed to the registered custom recognition."\n        }\n    },\n    "allOf": [\n        {\n            "if": {\n                "properties": {\n                    "custom_recognition": {\n                        "const": "ExampleRecognition"\n                    }\n                },\n                "required": [\n                    "custom_recognition"\n                ]\n            },\n            "then": {\n                "properties": {\n                    "custom_recognition_param": {\n                        "$ref": "#/$defs/ExampleRecognitionParam"\n                    }\n                }\n            }\n        }\n    ]\n}\n',
