    'import * as multilineArrays from "prettier-plugin-multiline-arrays";\nimport * as maafwSort from "@nekosu/prettier-plugin-maafw-sort";\n\nexport default {\n    plugins: [\n        maafwSort.patchPlugin(multilineArrays),\n    ],\n    multilineArraysWrapThreshold: 1,\n    maafwPipelinePatterns: [\n        "/pipeline/.*\\\\.jsonc?",\n    ],\n    maafwInterfacePatterns: [\n        "/interface\\\\.jsonc?",\n        "/tasks/.*\\\\.jsonc?",\n    ],\n    tabWidth: 4,\n    printWidth: 120,\n    useTabs: false,\n    bracketSameLine: true,\n    bracketSpacing: false,\n    endOfLine: "lf",\n    overrides: [\n        {\n            files: [\n                "**/*.yml",\n                "**/*.yaml",\n            ],\n            options: {\n                parser: "yaml",\n                tabWidth: 2,\n            },\n        },\n        {\n            files: [\n                "*.json",\n                "*.jsonc",\n            ],\n            options: {\n                parser: "json",\n                useTabs: false,\n                bracketSameLine: false,\n                trailingComma: "none",\n            },\n        },\n        {\n            files: [\n                "*.mts",\n                "**/*.ts",\n            ],\n            options: {\n                tabWidth: 2,\n                semi: false,\n                trailingComma: "all",\n                bracketSpacing: true,\n                singleQuote: true,\n                multilineArraysWrapThreshold: -1,\n            },\n        },\n    ],\n};\n',
  'base/README.en.md':
    '# {{displayName}}\n\nMaaFW project generated by create-maa-project.\n\n## Development\n\nThe project entry configuration is `interface.json`; tasks live in `tasks/` and resources in `resource/`.\n\nIf `package.json` exists at the project root, the development tooling is enabled and you can run:\n\n```bash\npnpm install\npnpm check\n```\n\nOtherwise, run `create-maa-project --add dev-tools` when you want formatting, validation, and editor setup.\n\n## Release\n\nIf `.github/workflows/release.yml` exists, pushing a tag such as `v{{version}}` triggers a release.\nOtherwise, run `create-maa-project --add github` to add CI and release automation.\n\nChinese documentation: [README.md](./README.md)\n',
  'base/README.md':
    '# {{displayName}}\n\n由 create-maa-project 生成的 MaaFW 项目。\n\n## 开发\n\n项目入口配置为 `interface.json`，任务定义在 `tasks/`，资源位于 `resource/`。\n\n如果根目录存在 `package.json`，说明已启用开发工具，可运行：\n\n```bash\npnpm install\npnpm check\n```\n\n未启用时，可按需运行 `create-maa-project --add dev-tools` 添加格式化、校验和编辑器配置。\n\n## 发布\n\n如果存在 `.github/workflows/release.yml`，推送 `v{{version}}` 这样的 tag 会触发发布。\n未启用时，可运行 `create-maa-project --add github` 添加 CI 和 Release 自动化。\n\nEnglish documentation: [README.en.md](./README.en.md)\n',
  'base/gitignore.tmpl':
    '# BEGIN create-maa-project\nnode_modules/\n.venv/\n.uv-cache/\n__pycache__/\nconfig/\ndist/\ndebug/\n.create-maa-project/\n# END create-maa-project\n',
  'base/interface.json.tmpl':
    '{\n    "interface_version": 2,\n    "name": "{{slug}}",\n    "label": "{{displayName}}",\n    "version": "{{version}}",\n    "description": "{{description}}",\n    "controller": {{controller}},\n    "resource": {{resources}},\n    "import": [\n        "./tasks/tutorial.json"\n    ]{{agentBlock}}\n}\n',
